mapper.select:

where r.enterprise_id = #{enterpriseId}

    and r.product_id = #{productId}


    and r.record_type = #{recordType}


    and r.create_time >= concat(#{beginTime}, ' 00:00:00')


    and r.create_time <= concat(#{endTime}, ' 23:59:59')

order by r.record_id desc

mapper.update:
update t_stock_record
set reverse_flag = '1', reverse_record_id = #{reverseRecordId}
where enterprise_id = #{enterpriseId} and record_id = #{recordId} and reverse_flag = '0'
